def _greedy_run(n, links, caps, parts, dist, origins, rng=None, pdist=None):
    adj, Cset = _adjacency(n, links, caps, parts)
    names = [p[0] for p in parts]
    router = Router(n, links, caps)
    routes = []
    recipes = []
    memo = {}
    trees = []
    for (v, rv) in origins:
        if len(trees) > 8000 or len(routes) > 32000 or len(recipes) > 65000:
            return None
        others = [w for (w, _rw) in parts if w != v]
        orders = _candidate_orders(v, others, dist, adj, Cset, pdist)
        if rng is not None:
            orders = orders + [rng.sample(others, len(others))
                               for _ in range(3)]
        done = None
        for order in orders:
            if set(order) != set(others) or len(order) != len(others):
                continue
            for strict in (False, True):
                saved_res = list(router.res)
                saved_routes = len(routes)
                saved_recipes = len(recipes)
                saved_memo = dict(memo)
                res = _deliver(router, v, rv, order, names, n, dist, recipes,
                               memo, strict, pdist)
                okflag = res is not None
                if okflag:
                    recs = _decompose_trees(v, rv, res[0], parts)
                    if recs is None:
                        okflag = False
                if not okflag:
                    router.res = saved_res
                    del routes[saved_routes:]
                    del recipes[saved_recipes:]
                    memo.clear()
                    memo.update(saved_memo)
                    continue
                done = (res, recs)
                break
            if done is not None:
                break
        if done is None:
            return None
        (lv, flows), recs = done
        trees.extend(recs)
        for (u, w, cnt, rid) in flows:
            routes.append([u, w, cnt, rid])
    return {'trees': trees, 'routes': routes, 'recipes': recipes}


